def transform(grid):
    h = len(grid)
    out = [[0] * 7 for _ in range(h)]

    marker = next(( (r, c) for r, row in enumerate(grid)
                    for c, value in enumerate(row) if value == 5), None)
    if marker is None:
        return out

    mr, mc = marker
    x = mc - 8
    out[mr][x] = 5
    y = mr + 1

    # Read the 3x3 tiles column-wise, top to bottom.
    tiles = []
    for c0 in (0, 4):
        for r0 in range(0, h - 2, 4):
            cells = {(r, c) for r in range(3) for c in range(3)
                     if grid[r0 + r][c0 + c] != 0}
            if not cells:
                continue
            color = grid[r0 + next(iter(cells))[0]][c0 + next(iter(cells))[1]]

            if cells == {(0,0),(0,1),(1,0),(1,2),(2,1)}:
                kind, length = "C", 3
            elif cells == {(0,0),(0,2),(1,0),(1,2),(2,0),(2,1),(2,2)}:
                kind, length = "U", 2
            elif cells == {(0,0),(0,2),(1,1),(2,1)}:
                kind, length = "Y", 2
            elif cells == {(0,0),(0,1),(0,2),(1,1),(2,0),(2,2)}:
                kind, length = "D", 4
            else:
                continue
            tiles.append((kind, length, color))

    for kind, length, color in tiles:
        if kind == "Y":
            for i in range(length):
                if y + i < h:
                    out[y + i][x] = color
            y += length
        elif kind == "C":
            for i in range(length):
                if 0 <= x + i < 7 and y < h:
                    out[y][x + i] = color
            x += length - 1
            y += 1
        else:  # U and D extend left.
            for i in range(length):
                if 0 <= x - i < 7 and y < h:
                    out[y][x - i] = color
            x -= length - 1
            y += 1

    return out
